#!/usr/bin/env bash
set -euo pipefail
db="supabase_db_game-ai-la-ke-gia-mao";game="82000000-0000-4000-8000-000000000020";game2="82000000-0000-4000-8000-000000000030";room="82000000-0000-4000-8000-000000000010";p1="82000000-0000-4000-8000-000000000001";p2="82000000-0000-4000-8000-000000000002";p3="82000000-0000-4000-8000-000000000003"
run_as(){ docker exec "$db" psql -U postgres -d postgres -v ON_ERROR_STOP=1 -Atq -c "begin;set local role authenticated;select set_config('request.jwt.claim.sub','$1',true);$2;commit;"; }
cleanup(){ docker exec "$db" psql -U postgres -d postgres -q -c "delete from game_rewards where game_id in('$game','$game2');delete from final_guesses where game_id in('$game','$game2');delete from final_guess_options where game_id in('$game','$game2');delete from votes where voting_round_id in(select id from voting_rounds where game_id in('$game','$game2'));delete from voting_round_candidates where voting_round_id in(select id from voting_rounds where game_id in('$game','$game2'));delete from voting_rounds where game_id in('$game','$game2');delete from game_players where game_id in('$game','$game2');delete from games where id in('$game','$game2');delete from room_players where room_id='$room';delete from rooms where id='$room';delete from profiles where id in('$p1','$p2','$p3');delete from auth.users where id in('$p1','$p2','$p3');" >/dev/null 2>&1||true;rm -f /tmp/result_race_*;};trap cleanup EXIT
docker exec "$db" psql -U postgres -d postgres -v ON_ERROR_STOP=1 -q -c "insert into auth.users(id,email)values('$p1','rr1@test'),('$p2','rr2@test'),('$p3','rr3@test');insert into profiles(id,username,avatar_id)values('$p1','RR One','avatar_01'),('$p2','RR Two','avatar_02'),('$p3','RR Three','avatar_03');insert into rooms(id,code,created_by,host_id,game_type,status,max_players,create_request_id)values('$room','ABC237','$p1','$p1','impostor','in_game',3,'82000000-0000-4000-8000-000000000011');insert into room_players(room_id,player_id,seat,is_ready)values('$room','$p1',1,true),('$room','$p2',2,true),('$room','$p3',3,true);insert into games(id,room_id,round_number,status,category_id,keyword_id,phase_started_at,phase_ends_at,started_by,start_request_id,impostor_count,clue_seconds,discussion_seconds,eliminated_player_id)select '$game','$room',1,'vote_result',category_id,id,clock_timestamp()-interval'6 seconds',clock_timestamp()-interval'1 second','$p1','82000000-0000-4000-8000-000000000021',1,15,60,'$p3' from words limit 1;insert into game_players(game_id,player_id,role,turn_order)values('$game','$p1','normal',1),('$game','$p2','normal',2),('$game','$p3','impostor',3);"
run_as "$p1" "select advance_game_if_due();" >/tmp/result_race_advance1 2>&1&a=$!;run_as "$p2" "select advance_game_if_due();" >/tmp/result_race_advance2 2>&1&b=$!;wait "$a";wait "$b"
[[ "$(docker exec "$db" psql -U postgres -d postgres -Atq -c "select status||' '||count(*) from games join final_guess_options on game_id=games.id where games.id='$game' group by games.status")" == "final_guess 4" ]]||{ echo 'duplicate final guess initialization';exit 1;}
choice="$(docker exec "$db" psql -U postgres -d postgres -Atq -c "select id from final_guess_options where game_id='$game' limit 1")"
set +e;run_as "$p3" "select submit_final_guess('$choice');" >/tmp/result_race_guess1 2>&1&a=$!;run_as "$p3" "select submit_final_guess('$choice');" >/tmp/result_race_guess2 2>&1&b=$!;wait "$a";wait "$b";set -e
read -r status guesses rewards <<<"$(docker exec "$db" psql -U postgres -d postgres -Atq -F ' ' -c "select g.status,(select count(*)from final_guesses where game_id=g.id),(select count(*)from game_rewards where game_id=g.id)from games g where id='$game'")"
[[ "$status $guesses $rewards" == "result 1 3" ]]||{ echo "guess/reward race failed $status $guesses $rewards";exit 1;}
run_as "$p1" "select play_again();" >/tmp/result_race_play1 2>&1&a=$!;run_as "$p1" "select play_again();" >/tmp/result_race_play2 2>&1&b=$!;wait "$a";wait "$b"
read -r room_status reward_count <<<"$(docker exec "$db" psql -U postgres -d postgres -Atq -F ' ' -c "select r.status,count(gr.id)from rooms r join games g on g.room_id=r.id left join game_rewards gr on gr.game_id=g.id where r.id='$room'group by r.status")"
[[ "$room_status $reward_count" == "waiting 3" ]]||{ echo "play again race failed $room_status $reward_count";exit 1;}
docker exec "$db" psql -U postgres -d postgres -v ON_ERROR_STOP=1 -q -c "update rooms set status='in_game' where id='$room';insert into games(id,room_id,round_number,status,category_id,keyword_id,phase_started_at,phase_ends_at,started_by,start_request_id,impostor_count,clue_seconds,discussion_seconds,eliminated_player_id)select '$game2','$room',2,'final_guess',category_id,id,clock_timestamp(),clock_timestamp()+interval'500 milliseconds','$p1','82000000-0000-4000-8000-000000000031',1,15,60,'$p3' from words limit 1;insert into game_players(game_id,player_id,role,turn_order)values('$game2','$p1','normal',1),('$game2','$p2','normal',2),('$game2','$p3','impostor',3);insert into final_guess_options(game_id,word_id,display_order)select '$game2',id,row_number()over()::integer from words limit 4;"
choice2="$(docker exec "$db" psql -U postgres -d postgres -Atq -c "select id from final_guess_options where game_id='$game2' limit 1")"
sleep .6
set +e;run_as "$p3" "select submit_final_guess('$choice2');" >/tmp/result_race_boundary_guess 2>&1&a=$!;run_as "$p1" "select advance_game_if_due();" >/tmp/result_race_boundary_advance 2>&1&b=$!;wait "$a";wait "$b";set -e
run_as "$p2" "select advance_game_if_due();" >/dev/null
read -r boundary_status boundary_reason boundary_guesses boundary_rewards <<<"$(docker exec "$db" psql -U postgres -d postgres -Atq -F ' ' -c "select g.status,g.result_reason,(select count(*)from final_guesses where game_id=g.id),(select count(*)from game_rewards where game_id=g.id)from games g where id='$game2'")"
[[ "$boundary_status $boundary_reason $boundary_guesses $boundary_rewards" == "result impostor_final_guess_timeout 0 3" ]]||{ echo "submit/timeout race failed $boundary_status $boundary_reason $boundary_guesses $boundary_rewards";exit 1;}
echo "PASS: advance, guess/timeout, duplicate resolution/rewards and Play Again races serialize"
